<?php require_once __DIR__ . "/../../../wp-load.php"; $books = get_posts(array("post_type" => "book","posts_per_page" => 4)); foreach ($books as $book) { $thumb_id = get_post_thumbnail_id($book->ID); echo "Book: {$book->post_title}\n"; echo "Thumb ID: " . ($thumb_id ?: "none") . "\n"; if ($thumb_id) { $src = wp_get_attachment_image_src($thumb_id, "book-cover"); var_export($src); echo "\n"; } echo "---\n"; } ?>
